mapper.select:
SELECT id, name, plugin_type, retry_times, retry_interval, timeout, enabled, description, current_task_definition_id, current_revision, update_time FROM ifj_task
retired = FALSE AND current_task_definition_id IS NOT NULL AND current_revision IS NOT NULL AND id = #{id}
AND name LIKE CONCAT('%', #{name}, '%')
AND plugin_type = #{pluginType}
AND enabled = #{enabled}
AND EXISTS ( SELECT 1 FROM ifj_task_definition_group definition_group WHERE definition_group.definition_id = current_task_definition_id AND definition_group.group_code = #{group} )
ORDER BY update_time DESC, id DESC

SELECT id, name, plugin_type, retry_times, retry_interval, timeout, enabled, description, current_task_definition_id, current_revision, update_time FROM ifj_task
retired = FALSE AND current_task_definition_id IS NOT NULL AND current_revision IS NOT NULL AND id = #{id}
AND LOWER(name) LIKE LOWER(CONCAT('%', #{name}, '%'))
AND plugin_type = #{pluginType}
AND enabled = #{enabled}
AND EXISTS ( SELECT 1 FROM ifj_task_definition_group definition_group WHERE definition_group.definition_id = current_task_definition_id AND definition_group.group_code = #{group} )
ORDER BY update_time DESC, id DESC

